from solution import specialFilter
import pytest
from hypothesis import given
import hypothesis.strategies as st


ODD = {'1', '3', '5', '7', '9'}

def reference(nums):
    count = 0
    for x in nums:
        if x > 10 and str(x)[0] in ODD and str(x)[-1] in ODD:
            count += 1
    return count

def qualifies(x):
    return x > 10 and str(x)[0] in ODD and str(x)[-1] in ODD


# --- concrete examples from spec ---
def test_example_1():
    assert specialFilter([15, -73, 14, -15]) == 1

def test_example_2():
    assert specialFilter([33, -2, -3, 45, 21, 109]) == 2


# --- boundary around "greater than 10" ---
def test_boundary_10_not_counted():
    # 10 is not > 10
    assert specialFilter([10]) == 0

def test_boundary_11_is_counted():
    # 11 > 10 and first=1 odd, last=1 odd
    assert specialFilter([11]) == 1

def test_boundary_11_in_list():
    assert specialFilter([11, 15, 14, 10, 12]) == 2  # 11 and 15 only

def test_boundary_12_last_digit_even():
    assert specialFilter([12]) == 0

def test_boundary_13_counted():
    assert specialFilter([13]) == 1

def test_boundary_9_10_11():
    assert specialFilter([9, 10, 11]) == 1

def test_first_digit_even_not_counted():
    # 21: first 2 even -> no; 45: both odd -> yes; 22: no
    assert specialFilter([21]) == 0
    assert specialFilter([45]) == 1
    assert specialFilter([22]) == 0

def test_last_digit_even_not_counted():
    assert specialFilter([14]) == 0
    assert specialFilter([16]) == 0
    assert specialFilter([33]) == 1
    assert specialFilter([39]) == 1

def test_empty_list():
    assert specialFilter([]) == 0

def test_all_negative_or_small_not_counted():
    assert specialFilter([-73, -15, -2, -3, 0, 5, 9, 10]) == 0

def test_negative_odd_digits_still_not_counted_because_not_gt_10():
    # -73, -15, -33, -11 all have odd digits but are not > 10
    assert specialFilter([-73, -15, -33, -11, -111]) == 0

def test_three_digit_boundaries():
    # 109: first 1 odd, last 9 odd, >10 -> counted
    assert specialFilter([109]) == 1
    # 209: first 2 even -> not counted
    assert specialFilter([209]) == 0
    # 210: first 2 even, last 0 even -> not counted
    assert specialFilter([210]) == 0
    # 111: counted
    assert specialFilter([111]) == 1


# --- property-based tests vs reference model ---
@given(st.lists(st.integers(min_value=-200, max_value=300), max_size=20))
def test_property_equivalence_to_reference(nums):
    assert specialFilter(nums) == reference(nums)

@given(st.lists(st.integers(min_value=0, max_value=30), max_size=20))
def test_property_equivalence_small_range_hits_10_11_boundary(nums):
    assert specialFilter(nums) == reference(nums)

@given(st.lists(st.integers(min_value=-1000, max_value=1000), max_size=30))
def test_property_count_within_bounds(nums):
    r = specialFilter(nums)
    assert isinstance(r, int)
    assert 0 <= r <= len(nums)

@given(st.lists(st.integers(min_value=-500, max_value=500), max_size=20))
def test_property_count_equals_sum_of_indicators(nums):
    r = specialFilter(nums)
    expected = sum(1 for x in nums if qualifies(x))
    assert r == expected

@given(st.lists(st.integers(min_value=-500, max_value=500), max_size=20))
def test_property_permutation_invariance(nums):
    assert specialFilter(list(reversed(nums))) == specialFilter(nums)
    assert specialFilter(sorted(nums)) == specialFilter(nums)

@given(st.lists(st.integers(min_value=-500, max_value=500), max_size=20), st.integers(min_value=-500, max_value=500))
def test_property_single_element_consistency(nums, x):
    # count of list with one appended element = old count + indicator
    base = specialFilter(nums)
    extended = specialFilter(nums + [x])
    assert extended == base + (1 if qualifies(x) else 0)

@given(st.lists(st.integers(min_value=-500, max_value=500), max_size=20))
def test_property_duplication_doubles_count(nums):
    assert specialFilter(nums + nums) == 2 * specialFilter(nums)

@given(st.lists(st.integers(min_value=-500, max_value=500), max_size=20))
def test_property_only_gt10_can_be_counted(nums):
    # removing all elements <= 10 must not change the result
    filtered = [x for x in nums if x > 10]
    assert specialFilter(nums) == specialFilter(filtered)

@given(st.lists(st.integers(min_value=11, max_value=200), max_size=20))
def test_property_idempotent_recount(nums):
    first = specialFilter(nums)
    # recounting qualifying-only sublist yields same count
    qual = [x for x in nums if qualifies(x)]
    assert specialFilter(qual) == first == len(qual)
